plugins: [
  // esbuild alias only supports bare module names; use a plugin to intercept
  // specific server source files that require CF-safe shims. We match by path
  // suffix so relative and package-alias imports are both caught.
  {
    name: "server-file-shims",
    setup(build) {
      // Match any import whose path ends with server/src/middleware/logger (any ext)
      build.onResolve({ filter: /\/middleware\/logger(\.tsx?|\.js)?$/ }, (args) => ({
        path: path.join(SHIMS, "server-logger-shim.ts"),
      }));
      // Match server/src/version.ts (loaded via createRequire → can't require JSON in CF)
      build.onResolve({ filter: /\/server\/src\/version(\.tsx?|\.js)?$/ }, (args) => ({
        path: path.join(SHIMS, "server-version-shim.ts"),
      }));
    },
  },
],

input.old_string:
plugins: [
  // esbuild alias only supports bare module names; use a plugin to intercept
  // specific server source files that require CF-safe shims.
  {
    name: "server-file-shims",
    setup(build) {
      const SERVER = path.resolve(__dirname, "../../server/src");
      const intercepts = [
        {
          real: path.join(SERVER, "middleware/logger.ts"),
          shim: path.join(SHIMS, "server-logger-shim.ts"),
          filter: /logger/,
        },
        {
          real: path.join(SERVER, "version.ts"),
          shim: path.join(SHIMS, "server-version-shim.ts"),
          filter: /version/,
        },
      ];
      for (const { real, shim, filter } of intercepts) {
        const realNoExt = real.replace(/\.ts$/, "");
        build.onResolve({ filter }, (args) => {
          const resolved = path.resolve(args.resolveDir, args.path);
          if (resolved === real || resolved === realNoExt) {
            return { path: shim };
          }
        });
      }
    },
  },
],
